(5946194, 866704, 98339, '<td valign="top">that would be a peach...not an apple...nice colors although</td>', 'that would be a peach...not an apple...nice colors although', '2010-04-14 12:04:04.000000', NULL, 1),
(5946196, 867414, 116573, '<td valign="top">Great color and nice use of background prop!</td>', 'Great color and nice use of background prop!', '2010-04-14 12:04:30.000000', NULL, 1),
(5946199, 867096, 116573, '<td valign="top">I like it!  Don''t know why ... just evokes a pleasant, easy feeling.</td>', 'I like it!  Don''t know why ... just evokes a pleasant, easy feeling.', '2010-04-14 12:05:33.000000', NULL, 1),
(5946201, 866508, 15711, '<td valign="top">Lovely.  If I were to change a thing, I''d either desaturate the border about 50% or more, or eliminate it completely.  I think it distracts from the beautiful light and flowers.  Great diagonal line.</td>', 'Lovely.  If I were to change a thing, I''d either desaturate the border about 50% or more, or eliminate it completely.  I think it distracts from the beautiful light and flowers.  Great diagonal line.', '2010-04-14 12:05:43.000000', NULL, 1),
(5946204, 867436, 15711, '<td valign="top">That looks just like my back door!!!  Did you sneak a bunny in there?  I love the high key feel of it with hardly any shadow tones.  The whiskers are great!</td>', 'That looks just like my back door!!!  Did you sneak a bunny in there?  I love the high key feel of it with hardly any shadow tones.  The whiskers are great!', '2010-04-14 12:07:05.000000', NULL, 1),
(5946205, 867204, 116573, '<td valign="top">I love everything about this ... composition, lighting, mood, title ... really great photo.</td>', 'I love everything about this ... composition, lighting, mood, title ... really great photo.', '2010-04-14 12:07:19.000000', NULL, 1),
(5946206, 866273, 15711, '<td valign="top">This has the feel of a pen and ink or charcoal drawing.  7</td>', 'This has the feel of a pen and ink or charcoal drawing.  7', '2010-04-14 12:08:04.000000', NULL, 1),
(5946208, 867525, 15711, '<td valign="top">Beautiful.  Very artfully presented.  I love the play of light, shadow and line. :)  8</td>', 'Beautiful.  Very artfully presented.  I love the play of light, shadow and line. :)  8', '2010-04-14 12:08:43.000000', NULL, 1),
(5946210, 867385, 116573, '<td valign="top">Neat!  And the title made me look for the missing wire!  Good color.</td>', 'Neat!  And the title made me look for the missing wire!  Good color.', '2010-04-14 12:09:08.000000', NULL, 1),
(5946211, 867294, 15711, '<td valign="top">Oh this is lovely.  Not always a fan of selective saturation, but this works. Love the narrow DOF 8</td>', 'Oh this is lovely.  Not always a fan of selective saturation, but this works. Love the narrow DOF 8', '2010-04-14 12:09:23.000000', NULL, 1),
(5946213, 866481, 116573, '<td valign="top">I like the mood and the soft focus in the background.</td>', 'I like the mood and the soft focus in the background.', '2010-04-14 12:10:00.000000', NULL, 1),
(5946214, 867437, 15711, '<td valign="top">Oh that''s lovely.  I love the curve of the rolled up sheer curtain, creating almost a rosette.  It adds a nice roundness to the otherwise geometric sense of the scene.  I like the juxtaposition.</td>', 'Oh that''s lovely.  I love the curve of the rolled up sheer curtain, creating almost a rosette.  It adds a nice roundness to the otherwise geometric sense of the scene.  I like the juxtaposition.', '2010-04-14 12:10:56.000000', NULL, 1),
(5946216, 867010, 116573, '<td valign="top">Very effective ... I can "feel" the texture of the wood and "smell" the dusty air!</td>', 'Very effective ... I can "feel" the texture of the wood and "smell" the dusty air!', '2010-04-14 12:11:02.000000', NULL, 1),
(5946217, 867165, 15711, '<td valign="top">Probably the only cat shot worthy of an entry.  Nice. :)</td>', 'Probably the only cat shot worthy of an entry.  Nice. :)', '2010-04-14 12:11:20.000000', NULL, 1),
(5946218, 867534, 116573, '<td valign="top">Really nice lines, lighting and composition.</td>', 'Really nice lines, lighting and composition.', '2010-04-14 12:12:18.000000', NULL, 1),
(5946220, 866957, 15711, '<td valign="top">I would have cropped to a landscape orientation, eliminating the stuffed animal.  Cute chihuahua (?). :)</td>', 'I would have cropped to a landscape orientation, eliminating the stuffed animal.  Cute chihuahua (?). :)', '2010-04-14 12:12:26.000000', NULL, 1),
(5946223, 867113, 104198, '<td valign="top">Looks a bit over sharpened, otherwise well done!</td>', 'Looks a bit over sharpened, otherwise well done!', '2010-04-14 12:12:45.000000', NULL, 1),
(5946224, 867218, 116573, '<td valign="top">Too dark to really make out the staircase.</td>', 'Too dark to really make out the staircase.', '2010-04-14 12:13:01.000000', NULL, 1),
(5946229, 867433, 96751, '<td valign="top">Fabulous detail!!!  Great conversion</td>', 'Fabulous detail!!!  Great conversion', '2010-04-14 12:14:38.000000', NULL, 1),
(5946230, 866609, 104198, '<td valign="top">Very colorful, but so "busy" I cannot narrow down the subject.</td>', 'Very colorful, but so "busy" I cannot narrow down the subject.', '2010-04-14 12:14:39.000000', NULL, 1),
(5946231, 866036, 96751, '<td valign="top">I love ratties!  I also love the backlit little pink ears.  And I''m guessing East coast from the radiator....</td>', 'I love ratties!  I also love the backlit little pink ears.  And I''m guessing East coast from the radiator....', '2010-04-14 12:15:14.000000', NULL, 1),
(5946233, 867516, 96751, '<td valign="top">Gorgeous kitty.  Incredible eyes.  Don''t know if the shallow dof works for this.</td>', 'Gorgeous kitty.  Incredible eyes.  Don''t know if the shallow dof works for this.', '2010-04-14 12:15:59.000000', NULL, 1),
(5946235, 867525, 96751, '<td valign="top">Nice shadow abstract</td>', 'Nice shadow abstract', '2010-04-14 12:16:19.000000', NULL, 1),
