(5946240, 867584, 116573, '<td valign="top">Beautiful subject, nice lighting.  Wrinkles in the background cloth were distracting</td>', 'Beautiful subject, nice lighting.  Wrinkles in the background cloth were distracting', '2010-04-14 12:16:59.000000', NULL, 1),
