(5946261, 867071, 96751, '<td valign="top">This might have been even stronger cropped at the bottom X, to eliminate the cars.</td>', 'This might have been even stronger cropped at the bottom X, to eliminate the cars.', '2010-04-14 12:23:02.000000', NULL, 1),
(5946265, 867397, 96751, '<td valign="top">Love the contrast of high detail on the stem with the background blur.  Very psychodelic.  Front page.</td>', 'Love the contrast of high detail on the stem with the background blur.  Very psychodelic.  Front page.', '2010-04-14 12:24:00.000000', NULL, 1),
(5946267, 867456, 96751, '<td valign="top">Sweet kitty.  Front page for all animal lovers.</td>', 'Sweet kitty.  Front page for all animal lovers.', '2010-04-14 12:24:23.000000', NULL, 1),
(5946270, 867422, 96751, '<td valign="top">Waaaaay too oversharpened.  With the textures, lighting, and colors, This would have looked better without it.</td>', 'Waaaaay too oversharpened.  With the textures, lighting, and colors, This would have looked better without it.', '2010-04-14 12:25:02.000000', NULL, 1),
(5946274, 866506, 96751, '<td valign="top">Lovely delicate colors, and soft lighting.  LOVE the blur on this.  I hope you''ll share how you did it.  Or PM me after the challenge :-)</td>', 'Lovely delicate colors, and soft lighting.  LOVE the blur on this.  I hope you''ll share how you did it.  Or PM me after the challenge :-)', '2010-04-14 12:25:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5946277, 866355, 96751, '<td valign="top">The clarity on this is breathtaking.  Jason, is that you?</td>', 'The clarity on this is breathtaking.  Jason, is that you?', '2010-04-14 12:26:34.000000', NULL, 1),
(5946278, 866277, 96751, '<td valign="top">Gorgeous child and portrait.  Excellent dof control.  Front page.</td>', 'Gorgeous child and portrait.  Excellent dof control.  Front page.', '2010-04-14 12:27:10.000000', NULL, 1),
(5946281, 867165, 96751, '<td valign="top">I love when cats get that look.  S/he looks a tad blurred around the nose.  Good choice with the sepia.</td>', 'I love when cats get that look.  S/he looks a tad blurred around the nose.  Good choice with the sepia.', '2010-04-14 12:27:49.000000', NULL, 1),
(5946282, 867379, 96751, '<td valign="top">That''s one heck of a hall!!</td>', 'That''s one heck of a hall!!', '2010-04-14 12:28:26.000000', NULL, 1),
(5946283, 867320, 96751, '<td valign="top">I love this.  Front page.</td>', 'I love this.  Front page.', '2010-04-14 12:28:58.000000', NULL, 1),
(5946290, 866912, 96751, '<td valign="top">Beautiful</td>', 'Beautiful', '2010-04-14 12:37:50.000000', NULL, 1),
(5946291, 867289, 96751, '<td valign="top">LOL!!!  The tilt really works.  Can''t wait to read how you did this.  Hope you''ll share.</td>', 'LOL!!!  The tilt really works.  Can''t wait to read how you did this.  Hope you''ll share.', '2010-04-14 12:38:25.000000', NULL, 1),
(5946292, 867294, 96751, '<td valign="top">Lovely image.  Great dof control, lighting, and bokeh.</td>', 'Lovely image.  Great dof control, lighting, and bokeh.', '2010-04-14 12:39:03.000000', NULL, 1),
(5946293, 865915, 96751, '<td valign="top">Fun image.  Really like the crop, and how the dof affected his chain.</td>', 'Fun image.  Really like the crop, and how the dof affected his chain.', '2010-04-14 12:39:45.000000', NULL, 1),
(5946296, 867437, 96751, '<td valign="top">Wonderful abstract/still life.  The rolled curtain is sheer genius (with pun most certainly intended), and the textured glass on the right, gorgeous.  Lighting, b/w tones, and horizontal balance all wonderful.  Front page.</td>', 'Wonderful abstract/still life.  The rolled curtain is sheer genius (with pun most certainly intended), and the textured glass on the right, gorgeous.  Lighting, b/w tones, and horizontal balance all wonderful.  Front page.', '2010-04-14 12:41:19.000000', NULL, 1),
(5946298, 867454, 96751, '<td valign="top">I want to shop at YOUR supermarket!</td>', 'I want to shop at YOUR supermarket!', '2010-04-14 12:42:31.000000', NULL, 1),
(5946299, 866470, 96751, '<td valign="top">Strong subject.  Not crazy about the background (though obviously in its natural setting).</td>', 'Strong subject.  Not crazy about the background (though obviously in its natural setting).', '2010-04-14 12:43:29.000000', NULL, 1),
(5946302, 867584, 96751, '<td valign="top">I always thought these flowers were such show offs :-)  Nice set-up, but I''m guessing you''ll get comments on the wrinkled backdrop...</td>', 'I always thought these flowers were such show offs :-)  Nice set-up, but I''m guessing you''ll get comments on the wrinkled backdrop...', '2010-04-14 12:45:26.000000', NULL, 1),
(5946304, 866809, 96751, '<td valign="top">Simple yet textured and visually appealing.  Love the desat on this.  Perhaps a tad oversharpened.</td>', 'Simple yet textured and visually appealing.  Love the desat on this.  Perhaps a tad oversharpened.', '2010-04-14 12:46:47.000000', NULL, 1),
(5946305, 867402, 96751, '<td valign="top">Love macros like this!</td>', 'Love macros like this!', '2010-04-14 12:46:57.000000', NULL, 1),
