INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5947945, 867267, 59633, '<td valign="top">What a beautiful and peaceful picture! Love the combination of white and pink.</td>', 'What a beautiful and peaceful picture! Love the combination of white and pink.', '2010-04-15 12:02:26.000000', NULL, 1),
(5947947, 867402, 59633, '<td valign="top">Very nice!</td>', 'Very nice!', '2010-04-15 12:02:53.000000', NULL, 1),
(5947949, 867350, 59633, '<td valign="top">Very nice!</td>', 'Very nice!', '2010-04-15 12:03:59.000000', NULL, 1),
(5947981, 866222, 33672, '<td valign="top">Great texture!</td>', 'Great texture!', '2010-04-15 12:29:00.000000', NULL, 1),
(5948059, 866133, 111625, '<td valign="top">Seems a little grainy, and sadistic</td>', 'Seems a little grainy, and sadistic', '2010-04-15 13:19:13.000000', NULL, 1),
(5948075, 866036, 115613, '<td valign="top">A little hot behind his haed but a great shot none the less</td>', 'A little hot behind his haed but a great shot none the less', '2010-04-15 13:32:16.000000', NULL, 1),
(5948079, 866995, 115613, '<td valign="top">The simplicity, composition and exposure are all excellent.</td>', 'The simplicity, composition and exposure are all excellent.', '2010-04-15 13:35:27.000000', NULL, 1),
(5948083, 867174, 115613, '<td valign="top">I think the surrounding white is a bit bright and might remove the stalks on the right and left but overall is a beautiful image.</td>', 'I think the surrounding white is a bit bright and might remove the stalks on the right and left but overall is a beautiful image.', '2010-04-15 13:39:13.000000', NULL, 1),
(5948085, 866422, 115307, '<td valign="top">The focus and general focus of this image are well done. However, I do not find this image particularly interesting. I think the subject and bland colors have something to do with that.</td>', 'The focus and general focus of this image are well done. However, I do not find this image particularly interesting. I think the subject and bland colors have something to do with that.', '2010-04-15 13:42:05.000000', NULL, 1),
(5948086, 867276, 115613, '<td valign="top">A lovely image, I might apply a bit of Shadow/Highlights to lighten up the front.</td>', 'A lovely image, I might apply a bit of Shadow/Highlights to lighten up the front.', '2010-04-15 13:42:39.000000', NULL, 1),
(5948087, 866995, 115307, '<td valign="top">Cute idea :-) I don''t think I would have "gotten it" or appreciated this photo without the title though. Maybe a shot from a higher perspective would show the "sunshine in the bucket more obviously.</td>', 'Cute idea :-) I don''t think I would have "gotten it" or appreciated this photo without the title though. Maybe a shot from a higher perspective would show the "sunshine in the bucket more obviously.', '2010-04-15 13:43:43.000000', NULL, 1),
(5948089, 867332, 115307, '<td valign="top">I think the jaggedy edges of your model are somewhat distracting. This is especially noticable on her face. The crooked horizon is also somewhat disorienting.<br/>I like the colors though, and I like the exposure you chose.</td>', 'I think the jaggedy edges of your model are somewhat distracting. This is especially noticable on her face. The crooked horizon is also somewhat disorienting.I like the colors though, and I like the exposure you chose.', '2010-04-15 13:46:34.000000', NULL, 1),
(5948090, 867224, 115307, '<td valign="top">While this photo has beautiful colors, I think it is lacking in some sharpness.</td>', 'While this photo has beautiful colors, I think it is lacking in some sharpness.', '2010-04-15 13:47:07.000000', NULL, 1),
(5948093, 866059, 115307, '<td valign="top">Very cute and creative idea :-)<br/>I like the color tones and the cat''s expression.<br/>I do wish that the cat was in as sharp of focus as the horse.</td>', 'Very cute and creative idea :-)I like the color tones and the cat''s expression.I do wish that the cat was in as sharp of focus as the horse.', '2010-04-15 13:47:59.000000', NULL, 1),
(5948095, 866953, 115307, '<td valign="top">I am confused as to why their appears to be motion blur in the reflection of the ball. Maybe its just the distortion of the reflection?</td>', 'I am confused as to why their appears to be motion blur in the reflection of the ball. Maybe its just the distortion of the reflection?', '2010-04-15 13:49:17.000000', NULL, 1),
(5948102, 866801, 115307, '<td valign="top">I like the composition of this image.<br/>I do have some issues with the black and white conversion here however. The overall coloring is too "midtone grey" for lack of a better way to describe it. The best black white images still have a full range of colors from white to light to midtone to dark to black. While this image has some highlights and shadows, they are not strong enough in order to make this photo more interesting. I think what you need is more contrast.<br/>Haha, sorry if this comment has too much critisism, I am not trying to slam your photo. I am just trying to help with what I see as an easily fixable flaw. Take anything I say with a grain of salt anyways :-)</td>', 'I like the composition of this image.I do have some issues with the black and white conversion here however. The overall coloring is too "midtone grey" for lack of a better way to describe it. The best black white images still have a full range of colors from white to light to midtone to dark to black. While this image has some highlights and shadows, they are not strong enough in order to make this photo more interesting. I think what you need is more contrast.Haha, sorry if this comment has too much critisism, I am not trying to slam your photo. I am just trying to help with what I see as an easily fixable flaw. Take anything I say with a grain of salt anyways :-)', '2010-04-15 13:54:47.000000', NULL, 1),
(5948114, 867230, 115307, '<td valign="top">ACW=All Comments Welcome? Well, thats what I am taking it as. My apologies if it really means "Apples can''t walk" or "Always channels water" :-P<br/>I love this photo as a thumb! In fact it was one of the photos I was most interested in viewing when looking through all of the thumbs. Up close, I like the focus in the "cold" handle and in the towel, but am missing some focus in the nozzle. That kind of detracts for me.<br/>I like the tonal range of your black white image. A nice mix of all shades, which is really important in my opinion.</td>', 'ACW=All Comments Welcome? Well, thats what I am taking it as. My apologies if it really means "Apples can''t walk" or "Always channels water" :-PI love this photo as a thumb! In fact it was one of the photos I was most interested in viewing when looking through all of the thumbs. Up close, I like the focus in the "cold" handle and in the towel, but am missing some focus in the nozzle. That kind of detracts for me.I like the tonal range of your black white image. A nice mix of all shades, which is really important in my opinion.', '2010-04-15 14:00:08.000000', NULL, 1),
(5948120, 866870, 115307, '<td valign="top">I find this photo very interesting. There are many things to look at.</td>', 'I find this photo very interesting. There are many things to look at.', '2010-04-15 14:08:11.000000', NULL, 1),
(5948122, 866958, 115307, '<td valign="top">This must have been a tricky photo to obtain. I don''t really like the blown out window, but on the other hand realize that the inside wouldn''t be nicely exposed otherwise.<br/>Maybe if the curtains had been drawn, you would still be getting the same directional lighting, but the contrast between the window and everything else wouldn''t be so drastic.</td>', 'This must have been a tricky photo to obtain. I don''t really like the blown out window, but on the other hand realize that the inside wouldn''t be nicely exposed otherwise.Maybe if the curtains had been drawn, you would still be getting the same directional lighting, but the contrast between the window and everything else wouldn''t be so drastic.', '2010-04-15 14:10:52.000000', NULL, 1),
(5948125, 866236, 115307, '<td valign="top">That table could have used some cleaning prior to the shot. Lots of dust!<br/>I like this photo though. Rich colors and interesting composition.</td>', 'That table could have used some cleaning prior to the shot. Lots of dust!I like this photo though. Rich colors and interesting composition.', '2010-04-15 14:12:55.000000', NULL, 1),
(5948138, 866355, 115307, '<td valign="top">Very interesting photo! I love the colors, and there is a lot to look at.<br/>That person''s legs are very distracting, and keep drawing my eye away from the main part of the photo. But I am sure you are aware of this.<br/>My guess is you probably didn''t notice her until after this photo was uploaded, yes?<br/>And anyways, it is not enough of a problem to affect your score. The quality of this photo is there regardless.</td>', 'Very interesting photo! I love the colors, and there is a lot to look at.That person''s legs are very distracting, and keep drawing my eye away from the main part of the photo. But I am sure you are aware of this.My guess is you probably didn''t notice her until after this photo was uploaded, yes?And anyways, it is not enough of a problem to affect your score. The quality of this photo is there regardless.', '2010-04-15 14:20:09.000000', NULL, 1),
(5948142, 866434, 115307, '<td valign="top">Wow, I love this photo for its simplicity! I can''t predict how the mainstream voters feel, but you have certainly won me over! My favorite part of this photo is her eye and the hairs that are lightly covering it.</td>', 'Wow, I love this photo for its simplicity! I can''t predict how the mainstream voters feel, but you have certainly won me over! My favorite part of this photo is her eye and the hairs that are lightly covering it.', '2010-04-15 14:25:18.000000', NULL, 1),
(5948149, 866222, 115307, '<td valign="top">I love the texture presented in this photo! The lighting is also very nice.<br/>I have a guess as to who this could potentially be (a first for me), but am going to remain silent for fear of being wrong :-P. I''ll shoot you a smug comment when this challenge is over, in case I am right.<br/>The fact that the picture is untitled irks me a little. Anyone who can think of this as a subject matter, has the necessary brain power to think of a good title, I assure you :-). 7</td>', 'I love the texture presented in this photo! The lighting is also very nice.I have a guess as to who this could potentially be (a first for me), but am going to remain silent for fear of being wrong :-P. I''ll shoot you a smug comment when this challenge is over, in case I am right.The fact that the picture is untitled irks me a little. Anyone who can think of this as a subject matter, has the necessary brain power to think of a good title, I assure you :-). 7', '2010-04-15 14:29:48.000000', NULL, 1),
